-- ---------------------------------------------------------------------------
-- 098.1  A reply notifies the thread's author, carrying thread_id ALONE
-- ---------------------------------------------------------------------------
set role authenticated;
select set_config('test.uid', '00000000-0000-0000-0000-000000980003', false);
